_note":"Hồ sơ thầu, cần kiểm tra địa chỉ quầy bán lẻ."},{"district":"Huyện Càng Long","name":"Kafka Bookstore","address_line":"Ấp Đầu Giồng, xã Phương Thạnh cũ, huyện Càng Long","category":"nha_sach","phone":null,"tax_code":null,"source_key":"web:kafka-bookstore-phuong-thanh","source_url":"https://store.dubutbooks.com/thong-bao-danh-sach-dai-ly-du-but","verification_note":"Đại lý sách theo danh sách NXB, cần xác minh giờ mở cửa."},{"district":"Huyện Càng Long","name":"Văn phòng phẩm Phạm Oanh","address_line":"12 Nguyễn Đáng, khu vực Càng Long cũ","category":"van_phong_pham","phone":null,"tax_code":null,"source_key":"gmap:ChIJN1W_VwAToDER8o0T5gEwFb8","source_url":"https://www.google.com/maps/search/?api=1&query=VPP%20Ph%E1%BA%A1m%20Oanh%20C%C3%A0ng%20Long%20Tr%C3%A0%20Vinh&query_place_id=ChIJN1W_VwAToDER8o0T5gEwFb8","verification_note":"Cần xác minh khu vực và số nhà tránh nhầm Nguyễn Đáng TP Trà Vinh."},{"district":"Huyện Càng Long","name":"Thiết bị vi tính - VPP Trọng Hiếu","address_line":"Ấp 4A, xã An Trường cũ, huyện Càng Long","category":"van_phong_pham","phone":null,"tax_code":"2100686604","source_key":"web:vpp-trong-hieu-an-truong","source_url":"https://dauthau.asia/businesslistings/detail/CONG-TY-TNHH-MTV-THIET-BI-VI-TINH-VAN-PHONG-PHAM-TRONG-HIEU-168960/","verification_note":"Hồ sơ doanh nghiệp; cần xác minh điểm bán lẻ."},{"district":"Huyện Cầu Kè","name":"Nhà sách - VPP Vân Lợi","address_line":"181 đường 30 Tháng 4, khóm 5, thị trấn Cầu Kè cũ","category":"van_phong_pham","phone":"02943831221","tax_code":null,"source_key":"gmap:ChIJ-9_KRvxpoDERJHW0xYyOZxU","source_url":"https://www.google.com/maps/search/?api=1&query=Nh%C3%A0%20s%C3%A1ch%20V%C3%A2n%20L%E1%BB%A3i%20C%E1%BA%A7u%20K%C3%A8%20Tr%C3%A0%20Vinh&query_place_id=ChIJ-9_KRvxpoDERJHW0xYyOZxU","verification_note":"Tên Nhà sách Vân Lợi và VPP Vân Lợi là một địa chỉ, đã gộp."},{"district":"Huyện Cầu Kè","name":"Văn phòng phẩm Phương Duy","address_line":"239 đường 30 Tháng 4, thị trấn Cầu Kè cũ","category":"van_phong_pham","phone":"0939003901","tax_code":null,"source_key":"web:vpp-phuong-duy-239-304","source_url":"https://sotayvang.com/cua-hang-van-phong-pham-phuong-duy-tt-cau-ke/","verification_note":""},{"district":"Huyện Cầu Kè","name":"Văn phòng phẩm thầy Cường","address_line":"ĐT911, xã Thạnh Phú cũ, huyện Cầu Kè","category":"van_phong_pham","phone":"0856411502","tax_code":null,"source_key":"gmap:ChIJEzhHC91roDERV86urFHHhtc","source_url":"https://www.google.com/maps/search/?api=1&query=V%C4%83n%20ph%C3%B2ng%20ph%E1%BA%A9m%20th%E1%BA%A7y%20C%C6%B0%E1%BB%9Dng%20Tr%C3%A0%20Vinh&query_place_id=ChIJEzhHC91roDERV86urFHHhtc","verification_note":"Nguồn hiện hành có thể ghi Tam Ngãi; cần đối chiếu xã cũ."},{"district":"Huyện Cầu Kè","name":"Văn phòng phẩm Ngọc Anh","address_line":"Ấp 1, huyện Cầu Kè cũ (địa chỉ mới: xã Cầu Kè)","category":"van_phong_pham","phone":null,"tax_code":"2100380373","source_key":"web:vpp-ngoc-anh-cau-ke","source_url":"https://dauthau.asia/businesslistings/detail/HO-KINH-DOANH-VAN-PHONG-PHAM-NGOC-ANH-154977/","verification_note":"Hồ sơ hộ kinh doanh; chưa có số nhà, cần xác minh điểm bán."}]'::jsonb) AS x(district text,name text,address_line text,category text,phone text,tax_code text,source_key text,source_url text,verification_note text)), ins AS (
 INSERT INTO public.field_prospects
 (id,area_visit_id,owner_sub,name,address_line,province,district,category,phone,tax_code,note,status,source_kind,research_source_key,research_source_url,research_batch)
 SELECT
 (substr(s.digest,1,8)||'-'||substr(s.digest,9,4)||'-5'||substr(s.digest,14,3)||'-8'||substr(s.digest,18,3)||'-'||substr(s.digest,21,12))::uuid,
 NULL,'ef943de4-18f7-49ef-8340-eefb18855534',s.name,s.address_line,'Trà Vinh',s.district,s.category,
 s.phone,s.tax_code,
 'Nguồn internet 2026-11-21. Chưa ghé; GPS chưa xác minh. '||
 CASE WHEN s.verification_note<>'' THEN s.verification_note||' ' ELSE '' END||
 'Nguồn: '||s.source_url,
 'new','manual',s.source_key,s.source_url,'2026-11-21-tra-vinh-old-wave-01-three-districts'
 FROM src s
 WHERE s.district IN ('Thành phố Trà Vinh','Huyện Càng Long','Huyện Cầu Kè')
  AND s.source_url LIKE 'https://%'
  AND NOT EXISTS (SELECT 1 FROM public.customers c
    WHERE c.province='Trà Vinh' AND c.district=s.district AND lower(btrim(c.name))=lower(btrim(s.name)))
  AND NOT EXISTS (SELECT 1 FROM public.field_prospects p
    WHERE p.province='Trà Vinh' AND p.district=s.district
    AND (p.research_source_key=s.source_key
      OR (lower(btrim(p.name))=lower(btrim(s.name)) AND lower(btrim(p.address_line))=lower(btrim(s.address_line)))))
 ON CONFLICT (research_source_key) WHERE research_source_key IS NOT NULL DO NOTHING
 RETURNING district,name,phone,tax_code
)
SELECT district,COUNT(*)::int inserted,COUNT(*) FILTER(WHERE phone IS NOT NULL)::int phones,COUNT(*) FILTER(WHERE tax_code IS NOT NULL)::int tax_codes FROM ins GROUP BY district ORDER BY district;